  const wchar_t* labels[]={L"Bugün",L"Zil programı",L"Sesler ve tören",L"Ayarlar"};int ids[]={ID_HOME,ID_PROGRAM,ID_SOUNDS,ID_SETTINGS};for(int i=0;i<4;i++)gNav[i]=CreateWindowExW(0,L"BUTTON",labels[i],WS_CHILD|WS_VISIBLE|BS_OWNERDRAW,0,96+i*48,208,44,h,(HMENU)(INT_PTR)ids[i],gInst,0);
