  gList=CreateWindowExW(WS_EX_CLIENTEDGE,WC_LISTVIEWW,L"",WS_CHILD|LVS_REPORT|LVS_SINGLESEL|LVS_SHOWSELALWAYS,238,108,rc.right-268,rc.bottom-190,h,(HMENU)501,gInst,0);ListView_SetExtendedListViewStyle(gList,LVS_EX_FULLROWSELECT|LVS_EX_GRIDLINES);const wchar_t* cols[]={L"Gün",L"Saat",L"Etkinlik",L"Ses"};int widths[]={110,80,220,280};for(int i=0;i<4;i++){LVCOLUMNW c={};c.mask=LVCF_TEXT|LVCF_WIDTH;c.pszText=(LPWSTR)cols[i];c.cx=widths[i];ListView_InsertColumn(gList,i,&c);}FontControl(gList);
  AddCtl(h,L"BUTTON",L"+ Yeni zil",BS_PUSHBUTTON,238,rc.bottom-66,112,34,ID_ADD);AddCtl(h,L"BUTTON",L"Düzenle",0,358,rc.bottom-66,96,34,ID_EDIT);AddCtl(h,L"BUTTON",L"Sil",0,462,rc.bottom-66,70,34,ID_DELETE);
